/* start import list */

async function im_mm_x(index) {
    id_offset.push(0);
    x.push({
        id: gen_id(),

        sec_id: "AAAA",
        format: [],
        game: g.game,
        console: g.console,
        name: g.file_name,
    })

    im_mm_file_header(0, 0, x[index].format)
}

function im_mm_file_header(o, i, x) {
    id_offset.push(o);
    x.push({
        id: gen_id(),

        sec_id: ":zlA",
        u32_0: u32(o + 0),
        u32_4: u32(o + 4),
        //check this
        u32_8: u32(o + 8),
        //check this
        section_datapack: [],
    });

    globalThis.log_array = {
        p_offset: {
            offset: 0,
            array: [],
            pointers: [],
        },

    }

    g = {
        file_name: g.file_name,
        divisibility: 16,
        divisible_prev_value: [],
        type_string: g.type_string,
        debug: pk_debug,
        endian: g.endian,
        file_dir_type: 0,
        ordered_ref: 0,
        unordered_ref: 0,
        m: 0,
        oa: [],
        texture_patch_array: [],
        sound_patch_array: [],
        tex_anims: 0,
        mm_world_164_array: [],
        mm_model_array: [],
        mm_model_texture_anims_list_array: [],
        mm_model_anims_1_array: [],
        mm_model_anims_2_array: [],
        mm_Texture_array: [],
        mm_sound_list_array: [],
        mm_car_section_array: [],
        mm_car_text_related_array: [],
        mm_unknown_idk_sec_array: [],
        mm_some_model_link_array: [],
        mm_world_later_array: [],
        mm_item_maybe_array: [],
        mm_strange_array: [],
        mm_unknown_small_model_link_array: [],
        mm_car_3_texture_link_array: [],
        mm_font_array: [],
        mm_car_link_the_third_array: [],
        mm_interface_array: [],
        mm_object_array: [],
        mm_asdf_texture_link_array: [],
        mm_another_unknown_sec_array: [],
        mm_asdf_some_list_array: [],
        mm_text_array: [],
        mm_car_model_sec_array: [],
        mm_unknown_thing_array: [],
        mm_unknown_some_values_array: [],
        mm_asdf_array: [],
        mm_texture_anims_array: [],
        mm_sound_section_array: [],
        mm_sound_controls_array: [],
        mm_item_unknown_link_array: [],
        mm_car_array: [],
        mm_object_link_array: [],
        mm_unknown_array: [],
    }

    im_mm_datapack(12, 0, x[i].section_datapack)

    return x[i].id
    // 12 bytes;

}

function im_mm_datapack(o, i, x) {
    id_offset.push(o);
    x.push({
        id: gen_id(),

        sec_id: ";YXC",
        u32_0: u32(o + 0),
        u32_4: u32(o + 4),
        //amount?
        u32_8: u32(o + 8),
        //amount?
        u32_12: u32(o + 12),
        //amount?
        section_16_texture: [],
        u32_16: u32(o + 16),
        u32_20: u32(o + 20),
        //amount?
        u32_24: u32(o + 24),
        u32_28: u32(o + 28),
        section_28_sound: [],
        u32_32: u32(o + 32),
        //amount?
        section_36_color_table: [],
        u32_36: u32(o + 36),
        u32_40: u32(o + 40),
        section_model_texture_list: [],
        //amount?
        ordered: [],
        patch_list: [],
    });

    g.m = buffer.byteLength - u32(12)
    let patchlistoffset = 60
    // get_mm_patch_list(12, patchlistoffset)

    // x[i].patch_list = convert_arraybuffer_base64(buffer.slice(patchlistoffset, g.m))
    // x[i].ordered = convert_arraybuffer_base64(buffer.slice(g.m, buffer.byteLength))

    //  id_offset.push(o);x.push({id: gen_id(),          
    //     index_patch_list_buffer: buffer.slice(o, endoffset),
    //     ordered_list_buffer: buffer.slice(o, endoffset),
    //     offset_patch_list: buffer.slice(o, endoffset)
    // });
    g.datapack_offset = o
    g.datapack_ref = x

    im_mm_get_combined_patch_list(o, patchlistoffset, x[i].patch_list)

    for (let ii = 0; ii < u32(o + 12); ii++) {
        im_mm_Texture(u32(o + 16) + (ii * 16) + g.m, ii, x[i].section_16_texture);
    }
    for (let ii = 0; ii < u32(o + 24); ii++) {
        im_mm_sound_list(u32(o + 28) + (ii * 16) + g.m, ii, x[i].section_28_sound);
    }
    for (let ii = 0; ii < u32(o + 32); ii++) {
        im_mm_color_table(u32(o + 36) + (ii * 1024) + g.m, ii, x[i].section_36_color_table);
    }
    im_mm_ordered(g.m, x[i].ordered)

    for (let ii = 0; ii < u32(o + 40); ii++) {
        im_mm_model_texture_anims_list(u32(o + 44) + (ii * 12) + g.m, ii, x[i].section_model_texture_list);
    }

    return x[i].id
    // 48 bytes;

}
function im_mm_get_combined_patch_list(o, patch_offset, x) {
    let texture_offset = patch_offset

    patch_offset += u32(g.datapack_offset + 8) * 8
    let sound_offset = patch_offset

    patch_offset += u32(g.datapack_offset + 20) * 8
    let general_offset = patch_offset

    id_offset.push(o);
    x.push({
        id: gen_id(),

        sec_id: "ipll",
        texture: im_patch_list(texture_offset, u32(g.datapack_offset + 8), 't'),
        sound: im_patch_list(sound_offset, u32(g.datapack_offset + 20), 's'),
    })

    g.texture_patch_ref = x[0].texture
    g.sound_patch_ref = x[0].sound

    log_array.p_offset.offset = general_offset
    for (let i = 0; i < u32(g.datapack_offset + 4); i++) {
        log_array.p_offset.array.push(u32(general_offset + (i * 4)))
    }

    log_array.p_offset.array.sort(function(a, b) {
        return a - b;
    });
}
