function ex_mm_datapack(o, x) {
    let e = o + 48
    su32(o + 0, x.u32_0)
    su32(o + 4, x.u32_4)
    su32(o + 8, x.u32_8)
    su32(o + 12, x.u32_12)
    su32(o + 16, x.u32_16)
    su32(o + 20, x.u32_20)
    su32(o + 24, x.u32_24)
    su32(o + 28, x.u32_28)
    su32(o + 36, x.u32_36)
    su32(o + 32, x.u32_32)
    su32(o + 40, x.u32_40)
    su32(o + 44, x.u32_44)

    let ordered_length = x.u32_0
    let patch_offset = 60
    let patch_list_buffer = convert_base64_arraybuffer(x.patch_list)
    let ordered_list_buffer = convert_base64_arraybuffer(x.ordered)
    globalThis.patch_buffer = new ArrayBuffer(patch_list_buffer.byteLength)
    buffer_array.push(patch_buffer)
    dynamic_buffer = patch_buffer

    new Uint8Array(dynamic_buffer).set(new Uint8Array(patch_list_buffer), 0)
    e = e + x.patch_list.byteLength
    patch_buffer = patch_buffer.slice(0, e - o)

    globalThis.ordered_buffer = new ArrayBuffer(ordered_length)
    buffer_array.push(ordered_buffer)

    dynamic_buffer = ordered_buffer

    new Uint8Array(dynamic_buffer).set(new Uint8Array(ordered_list_buffer), 0)
    ordered_buffer = ordered_buffer.slice(0, e)

    // e = ex_s_offset(o + 16, e, ex_mm_Texture, x.section_16, 'down');
    // e = ex_s_offset(o + 28, e, ex_mm_sound_list, x.section_28, 'down');
    // e = ex_s_offset(o + 36, e, ex_mm_color_table, x.section_36, 'down');
    // e = ex_s_offset(o + 44, e, ex_mm_model_texture_anims_list, x.section_44, 'down');

    g.debug && ex_debug(o, x.sec_id);
    return e
}
function ex_mm_ordered(o, x) {
    globalThis.ordered_buffer = new ArrayBuffer(268435455)

    buffer_array.push(ordered_buffer)
    dynamic_buffer = ordered_buffer

    let aftero = o
    let e = o
    o = 0
    g.m = o
    g.ordered_ref = x.unordered[0]
    g.ordered_ref = x

    ex_mm_unordered(x.unordered[0])

    // switch (g.file_dir_type) {

    //     case ""#mm_file_header">File Header[04]</a>":
    //             e = ex_mm_basic(o, x.mm_file_specific_section[0])
    //         break

    //     case ""#mm_file_header">File Header[04]</a>":
    //             e = ex_mm_world(o, x.mm_file_specific_section[0])
    //         break

    // default:
    //     console.pk_log('file type is not set')
    // }

    let current_patch_list_divis = divisible(g.divisible_prev_value[0], g.divisible_prev_value[1])
    let patch_list_divis = divisible(g.divisible_prev_value[0] + 1, 4)
    e -= current_patch_list_divis
    e += patch_list_divis

    ordered_buffer = ordered_buffer.slice(0, e)

    buffer_array[buffer_array.length - 1] = ordered_buffer

    return e + aftero
}
